ALPHABET = "abcdefghijklmnopqrstuvwxyz"


def verschluesseln(text: str, schluessel: int = 3) -> str:
    """Verschiebt jeden Buchstaben um schluessel Stellen."""
    resultat = ""
    for zeichen in text:
        if zeichen.lower() in ALPHABET:
            position = ALPHABET.index(zeichen.lower())
            neu = ALPHABET[(position + schluessel) % 26]
            if zeichen.isupper():
                neu = neu.upper()
            resultat += neu
        else:
            resultat += zeichen
    return resultat


def entschluesseln(text: str, schluessel: int = 3) -> str:
    """Macht verschluesseln() rückgängig."""
    return verschluesseln(text, -schluessel)


geheim = verschluesseln("Hallo Welt")
print(geheim)
print(entschluesseln(geheim))

