def stats(werte: list) -> tuple:
    """Gibt (tiefster, höchster, Mittelwert) zurück."""
    tief = werte[0]
    hoch = werte[0]
    summe = 0
    for wert in werte:
        if wert < tief:
            tief = wert
        if wert > hoch:
            hoch = wert
        summe += wert
    return tief, hoch, round(summe / len(werte), 1)


def frosttage(werte: list) -> int:
    """Zählt die Tage unter 0 Grad."""
    anzahl = 0
    for wert in werte:
        if wert < 0:
            anzahl += 1
    return anzahl


def warme_tage(werte: list) -> list:
    """Tage (ab 1) mit einer Temperatur über dem Mittelwert."""
    schnitt = sum(werte) / len(werte)
    tage = []
    for tag, wert in enumerate(werte, start=1):
        if wert > schnitt:
            tage.append(tag)
    return tage


