print(f"Tiefstwert: {tief} °C")
print(f"Höchstwert: {hoch} °C")
print(f"Durchschnitt: {schnitt} °C")
print(f"Frosttage: {frosttage(temperaturen)}")
print(f"Warme Tage: {warme_tage(temperaturen)}")

