text = "Der Hund jagt den Ball. Der Ball rollt, der Hund bellt!"


def woerter_zaehlen(text: str) -> dict:
    """Zählt die Wörter eines Textes (klein geschrieben, ohne Satzzeichen)."""
    for zeichen in ".,!?":
        text = text.replace(zeichen, "")
    zaehler = {}
    for wort in text.lower().split():
        zaehler[wort] = zaehler.get(wort, 0) + 1
    return zaehler


def haeufigstes(zaehler: dict) -> tuple:
    """Gibt (wort, anzahl) des häufigsten Worts zurück."""
    bestes = None
    for wort in sorted(zaehler):
        if bestes is None or zaehler[wort] > zaehler[bestes]:
            bestes = wort
    return bestes, zaehler[bestes]


ergebnis = woerter_zaehlen(text)
wort, anzahl = haeufigstes(ergebnis)
print(f"Verschiedene Wörter: {len(ergebnis)}")
print(f"Häufigstes Wort: '{wort}' ({anzahl}x)")

