def collatz(n: int) -> list:
    """Gibt die Collatz-Folge von n bis 1 zurück."""
    folge = [n]
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        folge.append(n)
    return folge


def laengste(bis: int) -> tuple:
    """Sucht die Startzahl bis `bis` mit der längsten Folge."""
    beste_start = 1
    beste_laenge = 1
    for start in range(1, bis + 1):
        laenge = len(collatz(start))
        if laenge > beste_laenge:
            beste_start = start
            beste_laenge = laenge
    return beste_start, beste_laenge


print("collatz(6) =", collatz(6))
start, laenge = laengste(30)
print(f"Längste Folge bis 30: Start {start}, Länge {laenge}")

