    "Mutter": {"preis": 0.04, "menge": 50},
    "Hammer": {"preis": 12.5, "menge": 3},
    "Zange": {"preis": 8.0, "menge": 0},
}


def lagerwert(lager: dict) -> float:
    """Gesamtwert des Lagers in CHF."""
    summe = 0
    for artikel in lager.values():
        summe += artikel["preis"] * artikel["menge"]
    return round(summe, 2)


def nachbestellen(lager: dict, name: str, anzahl: int) -> bool:
    """Erhöht die Menge eines Artikels, falls er existiert."""
    if name in lager:
        lager[name]["menge"] += anzahl
        return True
    return False


def knapp(lager: dict, grenze: int) -> list:
    """Artikel mit einer Menge unter der Grenze, alphabetisch."""
    namen = []
    for name in lager:
        if lager[name]["menge"] < grenze:
            namen.append(name)
    return sorted(namen)


