def aus_ort(kontakte: list, ort: str) -> list:
    """Namen aller Kontakte aus einem Ort."""
    namen = []
    for kontakt in kontakte:
        if kontakt["ort"] == ort:
            namen.append(kontakt["name"])
    return namen


def durchschnittsalter(kontakte: list) -> float:
    """Durchschnittsalter, auf 0.1 gerundet."""
    summe = 0
    for kontakt in kontakte:
        summe += kontakt["alter"]
    return round(summe / len(kontakte), 1)


def speichern(kontakte: list) -> str:
    """Wandelt die Kontakte in einen JSON-Text um."""
    return json.dumps(kontakte, indent=2)


def laden(text: str) -> list:
    """Wandelt einen JSON-Text in eine Liste um."""
    return json.loads(text)


