import json

daten = [
    ("Anna", [5.5, 4.5, 6.0]),
    ("Ben", [4.0, 3.5, 4.5]),
    ("Cem", [5.0, 5.5, 5.0]),
    ("Dora", [3.5, 3.0, 4.0]),
]


def durchschnitte(daten: list) -> dict:
    """Durchschnittsnote pro Person, auf 0.1 gerundet."""
    schnitte = {}
    for name, noten in daten:
        schnitte[name] = round(sum(noten) / len(noten), 1)
    return schnitte


def rangliste(schnitte: dict) -> list:
    """Liste von (name, durchschnitt), beste zuerst."""
    paare = []
    for name in schnitte:
        paare.append((schnitte[name], name))
    paare.sort(reverse=True)
    ergebnis = []
    for schnitt, name in paare:
        ergebnis.append((name, schnitt))
    return ergebnis


def bestanden(schnitte: dict, grenze: float = 4.0) -> set:
    """Namen mit einem Durchschnitt ab der Grenze."""
    menge = set()
    for name in schnitte:
        if schnitte[name] >= grenze:
            menge.add(name)
    return menge


schnitte = durchschnitte(daten)
for platz, eintrag in enumerate(rangliste(schnitte), start=1):
    print(f"{platz}. {eintrag[0]}: {eintrag[1]}")
print("Bestanden:", sorted(bestanden(schnitte)))
